[CmdletBinding(SupportsShouldProcess=$true,ConfirmImpact='High')]
param([string]$ZipPath=(Join-Path $PSScriptRoot 'request-address-provider-performance-v173-final.zip'),[string]$ReleaseBasePath='D:\SOODALLIFE\releases',[string]$AppsRoot='D:\SOODALLIFE\apps',[string]$ServerInstance='localhost',[string]$DatabaseName='SOODAL_LIFE_DEV',[string]$DatabaseBackupRoot='D:\SOODALLIFE\DB\Backup',[switch]$ConfirmProductionDeployment)
$ErrorActionPreference='Stop';$expectedSha256='c95efa164aaf299884daf49a775fc5954cc84ee8d9e40cc3b50aacb20239ce84'
if(-not $ConfirmProductionDeployment){throw 'Safety stop: add -ConfirmProductionDeployment only after checking the ZIP hash and target paths.'}
